#pragma once

#include <string_view>

namespace KCDC::Shared::Game {
    /**
     * The game's armor types whose items never change condition (`armor_type.xml`,
     * `CanHealthChange="false"`): spurs, belts, pouches, horse tack and the like.
     * Generated by `tools/generate_clothing_armor_types.py`.
     */
    bool IsImmutableArmorType(std::string_view armorType);

    /** Whether a shipped clothing component (`CharacterComponent.xml`) carries one of those types, inherited down its tree. */
    bool IsImmutableClothingComponent(std::string_view component);
} // namespace KCDC::Shared::Game
